parameters.jsCode:
const f = $json.fields,
  keys = [
    "What's the title of your talk?",
    "Please share the abstract of your talk.",
    "Please share a URL of your profile picture.",
    "Your twitter handle",
    "Great, can we get your full name?",
    "Please share a bit of information about you.",
    "And what's your email address?",
  ];
if (!f || keys.some((k) => typeof f[k] !== "string"))
  throw Error("Provide all proposal fields as text");
return { json: $json, pairedItem: { item: $itemIndex } };

if ($json.status !== "completed" || !$json.uid || !$json.image_url)
  throw Error("Image did not complete");
return { json: $json, pairedItem: { item: $itemIndex } };

